def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    opp_defects = sum(1 for _, o in history if o == 'D')
    last_own, last_opp = history[-1]

    # Endgame: if opponent has never defected, exploit fully.
    if n >= 90:
        if opp_defects == 0:
            return 'D'
        else:
            return 'C' if last_opp == 'C' else 'D'

    # If opponent has never defected, alternate D and C to exploit.
    if opp_defects == 0:
        if n < 3:
            return 'C'
        return 'D' if last_own == 'C' else 'C'

    # Tit-for-Two-Tats: defect only if opponent defected twice in a row.
    if n >= 2:
        if history[-1][1] == 'D' and history[-2][1] == 'D':
            return 'D'

    # If opponent is defecting very frequently, defect as well.
    if opp_defects >= 3 and opp_defects >= n - opp_defects:
        return 'D'

    # Forgive a single defection.
    if last_opp == 'D':
        return 'C'

    return 'C'
